export const LAYOUTS: LayoutItem[] = [
  { id: 'mind-map', name: 'Mind Map', variants: mindMapVariants },
  { id: 'logic-chart', name: 'Logic Chart', variants: logicChartVariants },
  { id: 'brace-map', name: 'Brace Map', variants: braceMapVariants },
  { id: 'org-chart', name: 'Org Chart', variants: orgChartVariants },
  { id: 'tree-chart', name: 'Tree Chart', variants: treeChartVariants },
  { id: 'timeline', name: 'Timeline', variants: timelineVariants },
  { id: 'fishbone', name: 'Fishbone', variants: fishboneVariants },
  { id: 'tree-table', name: 'Tree Table', variants: treeTableVariants },
  { id: 'matrix', name: 'Matrix', variants: matrixVariants },
];

interface LayoutPickerPopoverProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (layoutId: string, layoutName: string, variantId: string, variantName: string) => void;
  anchorRef: React.RefObject<HTMLElement>;
}

export const LayoutPickerPopover: React.FC<LayoutPickerPopoverProps> = ({
  isOpen,
  onClose,
  onSelect,
  anchorRef,
}) => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) {
      setExpandedId(null);
    }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const handleClickOutside = (e: MouseEvent) => {
      if (
        popoverRef.current &&
        !popoverRef.current.contains(e.target as Node) &&
        anchorRef.current &&
        !anchorRef.current.contains(e.target as Node)
      ) {
        onClose();
      }
    };

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEscape);
    };
  }, [isOpen, onClose, anchorRef]);

  if (!isOpen) return null;

  const toggleExpand = (id: string) => {
    setExpandedId(prev => (prev === id ? null : id));
  };

  const handleSelectVariant = (layoutId: string, layoutName: string, variantId: string, variantName: string) => {
    onSelect(layoutId, layoutName, variantId, variantName);
    onClose();
  };

  // Calculate position - determine if popover should appear left or right of anchor
  const anchorRect = anchorRef.current?.getBoundingClientRect();
  const top = anchorRect ? anchorRect.top : 100;
  const popoverWidth = 310;
  const gap = 10;
  
  // Calculate left position (popover to the left of anchor)
  const leftPosition = anchorRect ? anchorRect.left - popoverWidth - gap : window.innerWidth - popoverWidth - gap - 210;
  
  // Calculate right position (popover to the right of anchor)
  const rightPosition = anchorRect ? anchorRect.right + gap : window.innerWidth - popoverWidth - 10;
  
  // Choose position based on available space
  // If left position would go off-screen (< 10px), use right position
  // If right position would go off-screen (> window.innerWidth - 10), use left position
  let finalLeft = leftPosition;
  if (leftPosition < 10) {
    finalLeft = rightPosition;
  }
  // Ensure we don't go off the right edge
  if (finalLeft + popoverWidth > window.innerWidth - 10) {
    finalLeft = window.innerWidth - popoverWidth - 10;
  }

  return (
    <div
      ref={popoverRef}
      style={{
        position: 'fixed',
        top: `${Math.max(20, top - 50)}px`,
        left: `${Math.max(10, finalLeft)}px`,
        width: `${popoverWidth}px`,
        minHeight: '530px',
        background: '#262626',
        borderRadius: '8px',
        boxShadow: '0 8px 24px rgba(0,0,0,0.5)',
        padding: '12px',
        display: 'flex',
        zIndex: 1000,
        fontFamily: 'Inter, "Segoe UI", sans-serif',
      }}
    >
      {/* Left menu column */}
      <div style={{ width: '160px', paddingRight: '8px' }}>
        {LAYOUTS.map(layout => {
          const isExpanded = expandedId === layout.id;
          return (
            <div
              key={layout.id}
              onClick={() => toggleExpand(layout.id)}
              style={{
                height: '40px',
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                padding: '0 8px',
                borderRadius: '4px',
                cursor: 'pointer',
                transition: 'background 0.15s',
                background: isExpanded ? '#333333' : 'transparent',
              }}
              onMouseEnter={(e) => {
                if (!isExpanded) e.currentTarget.style.background = '#333333';
              }}
              onMouseLeave={(e) => {
                if (!isExpanded) e.currentTarget.style.background = 'transparent';
              }}
            >
              <span
                style={{
                  fontSize: '10px',
                  color: '#cfcfcf',
                  transition: 'transform 0.2s',
                  transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                  display: 'inline-block',
                }}
              >
                ▸
              </span>
              <span style={{ fontSize: '14px', color: '#e6e6e6', fontWeight: 500 }}>
                {layout.name}
              </span>
            </div>
          );
        })}
      </div>

      {/* Right pane - submenu/preview */}
      <div
        style={{
          flex: 1,
          background: '#1e1e1e',
          borderRadius: '4px',
          padding: expandedId ? '8px' : '0',
          overflowY: 'auto',
          maxHeight: '500px',
        }}
      >
        {expandedId && (
          <>
            <div style={{ fontSize: '11px', color: '#8b8b8b', marginBottom: '8px', fontWeight: 600 }}>
              {LAYOUTS.find(l => l.id === expandedId)?.name} Variants
            </div>
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(3, 1fr)',
                gap: '8px',
              }}
            >
              {LAYOUTS.find(l => l.id === expandedId)?.variants.map(variant => (
                <div
                  key={variant.id}
                  onClick={() =>
                    handleSelectVariant(
                      expandedId,
                      LAYOUTS.find(l => l.id === expandedId)?.name || '',
                      variant.id,
                      variant.name
                    )
                  }
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: '6px',
                    padding: '8px 6px',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    transition: 'background 0.15s',
                  }}
                  onMouseEnter={(e) => (e.currentTarget.style.background = '#333333')}
                  onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
                >
                  <div
                    style={{
                      width: '44px',
                      height: '30px',
                      background: '#fff',
                      borderRadius: '3px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      flexShrink: 0,
                    }}
                  >
                    {variant.thumbnail}
                  </div>
                  <span style={{ fontSize: '10px', color: '#e0e0e0', textAlign: 'center', lineHeight: '1.2' }}>
                    {variant.name}
                  </span>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default LayoutPickerPopover;
